#include <vector>

class Solution {
public:
    std::vector<int> goodDaysToRobBank(std::vector<int>& security, int time) {
        int n = security.size();
        if (time == 0) {
            std::vector<int> all(n);
            for (int i = 0; i < n; ++i) all[i] = i;
            return all;
        }

        std::vector<int> left(n, 0);
        for (int i = 1; i < n; ++i) {
            if (security[i] <= security[i - 1]) left[i] = left[i - 1] + 1;
        }

        std::vector<int> right(n, 0);
        for (int i = n - 2; i >= 0; --i) {
            if (security[i] <= security[i + 1]) right[i] = right[i + 1] + 1;
        }

        std::vector<int> ans;
        for (int i = time; i < n - time; ++i) {
            if (left[i] >= time && right[i] >= time) ans.push_back(i);
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<Integer> goodDaysToRobBank(int[] security, int time) {
        int n = security.length;
        List<Integer> ans = new ArrayList<>();
        if (time == 0) {
            for (int i = 0; i < n; i++) ans.add(i);
            return ans;
        }

        int[] left = new int[n];
        for (int i = 1; i < n; i++) {
            if (security[i] <= security[i - 1]) left[i] = left[i - 1] + 1;
        }

        int[] right = new int[n];
        for (int i = n - 2; i >= 0; i--) {
            if (security[i] <= security[i + 1]) right[i] = right[i + 1] + 1;
        }

        for (int i = time; i < n - time; i++) {
            if (left[i] >= time && right[i] >= time) ans.add(i);
        }
        return ans;
    }
}

